const d = $json.desglose;
if (!d || d.facturable === false) {
  return [{ json: { facturable: false, servicio_id: d ? d.servicio_id : null } }];
}
return [{ json: d }];

// RAMA CFDI. OJO: los datos fiscales del receptor (RFC, régimen, uso, CP)
// NO están estructurados en la DB (contratos.datos_fiscales solo trae el
// flag FACTURA/REMISION). Definir la fuente real antes de producción.
const d = $json;
const concepto = {
  ProductCode: '80141600',
  UnitCode: 'E48',
  Unit: 'Servicio',
  Description: `Servicio ${d.tipo_servicio} · contrato ${d.contrato_id}${d.geocerca_nombre ? ' · ' + d.geocerca_nombre : ''}`,
  Quantity: 1,
  UnitPrice: d.subtotal,
  Subtotal: d.subtotal,
  Discount: 0,
  TaxObject: '02',
  Taxes: [{ Name: 'IVA', Rate: d.iva_tasa, Total: d.iva, Base: d.subtotal, IsRetention: false, IsFederalTax: true }],
  Total: d.total
};
const cfdi = {
  NameId: '1', CfdiType: 'I', ExpeditionPlace: '64000',
  PaymentForm: '03', PaymentMethod: 'PUE', Currency: 'MXN',
  Receiver: {
    // TODO: sustituir por datos fiscales reales del cliente
    Rfc: 'XAXX010101000', Name: d.cliente, CfdiUse: 'G03',
    FiscalRegime: '601', TaxZipCode: '64000'
  },
  Items: [concepto]
};
return [{ json: { cfdi, desglose: d } }];
